CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','DOCTOR','RECEPTIONIST')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, location VARCHAR(255), phone VARCHAR(50), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE patients (id BIGSERIAL PRIMARY KEY, patient_code VARCHAR(40) NOT NULL UNIQUE, full_name VARCHAR(255) NOT NULL, date_of_birth DATE NOT NULL, gender VARCHAR(30), phone VARCHAR(50), email VARCHAR(255), address TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE doctors (id BIGSERIAL PRIMARY KEY, department_id BIGINT NOT NULL REFERENCES departments(id), full_name VARCHAR(255) NOT NULL, specialty VARCHAR(120), phone VARCHAR(50), email VARCHAR(255) UNIQUE, consultation_fee NUMERIC(12,2) NOT NULL CHECK(consultation_fee>=0), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rooms (id BIGSERIAL PRIMARY KEY, department_id BIGINT NOT NULL REFERENCES departments(id), room_number VARCHAR(50) NOT NULL UNIQUE, room_type VARCHAR(80) NOT NULL, daily_rate NUMERIC(12,2) NOT NULL CHECK(daily_rate>=0), status VARCHAR(20) NOT NULL CHECK(status IN ('AVAILABLE','OCCUPIED','MAINTENANCE')), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patients(id), doctor_id BIGINT NOT NULL REFERENCES doctors(id), appointment_at TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('SCHEDULED','CONFIRMED','COMPLETED','CANCELLED')), reason TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admissions (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patients(id), doctor_id BIGINT NOT NULL REFERENCES doctors(id), room_id BIGINT NOT NULL REFERENCES rooms(id), admitted_at TIMESTAMP NOT NULL, discharged_at TIMESTAMP, diagnosis TEXT, status VARCHAR(20) NOT NULL CHECK(status IN ('ADMITTED','DISCHARGED')), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((status='ADMITTED' AND discharged_at IS NULL) OR (status='DISCHARGED' AND discharged_at IS NOT NULL)));
CREATE TABLE medicines (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, unit VARCHAR(50), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0), stock_quantity INT NOT NULL CHECK(stock_quantity>=0), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE prescriptions (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patients(id), doctor_id BIGINT NOT NULL REFERENCES doctors(id), admission_id BIGINT REFERENCES admissions(id), prescribed_at TIMESTAMP NOT NULL, notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE prescription_items (id BIGSERIAL PRIMARY KEY, prescription_id BIGINT NOT NULL REFERENCES prescriptions(id) ON DELETE CASCADE, medicine_id BIGINT NOT NULL REFERENCES medicines(id), dosage VARCHAR(100) NOT NULL, frequency VARCHAR(100) NOT NULL, duration_days INT NOT NULL CHECK(duration_days>0), quantity INT NOT NULL CHECK(quantity>0), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE billing (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patients(id), appointment_id BIGINT UNIQUE REFERENCES appointments(id), admission_id BIGINT UNIQUE REFERENCES admissions(id), issued_at DATE NOT NULL, total_amount NUMERIC(12,2) NOT NULL CHECK(total_amount>=0), status VARCHAR(20) NOT NULL CHECK(status IN ('UNPAID','PAID','VOID')), paid_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((appointment_id IS NOT NULL)::int + (admission_id IS NOT NULL)::int = 1));
CREATE INDEX idx_appointments_doctor_time ON appointments(doctor_id,appointment_at); CREATE INDEX idx_admissions_active_room ON admissions(room_id) WHERE status='ADMITTED'; CREATE INDEX idx_patients_search ON patients(full_name,patient_code,phone); CREATE INDEX idx_billing_status ON billing(status);
